
const WORDS=[{"id": 0, "w": "霞", "p": "xiá", "t": "名词", "m": "ráng mây, ánh mây màu lúc bình minh hoặc hoàng hôn", "coll": "晚霞、朝霞", "s": "傍晚时分，天边的霞把远处的山峰染成了红色。"}, {"id": 1, "w": "朴素", "p": "pǔsù", "t": "形容词", "m": "mộc mạc, giản dị", "coll": "穿着朴素、朴素的生活", "s": "这位老人虽然家境富裕，却一直过着朴素的生活。"}, {"id": 2, "w": "温和", "p": "wēnhé", "t": "形容词", "m": "hòa nhã, ôn hòa, điềm đạm", "coll": "态度温和、语气温和", "s": "老师用温和的语气指出问题，让学生更容易接受。"}, {"id": 3, "w": "颠簸", "p": "diānbǒ", "t": "动词", "m": "tròng trành, lắc lư, nghiêng ngả", "coll": "一路颠簸、道路颠簸", "s": "汽车在山路上颠簸了两个小时，才到达那个小村庄。"}, {"id": 4, "w": "巷", "p": "xiàng", "t": "名词", "m": "ngõ hẻm", "coll": "小巷、巷口", "s": "沿着这条巷一直往前走，就能看到那座老宅。"}, {"id": 5, "w": "陶瓷", "p": "táocí", "t": "名词", "m": "gốm sứ", "coll": "陶瓷制品、陶瓷工艺", "s": "博物馆里展出了许多精美的古代陶瓷制品。"}, {"id": 6, "w": "收藏", "p": "shōucáng", "t": "动词", "m": "thu thập, sưu tầm", "coll": "收藏文物、值得收藏", "s": "他从年轻时起就喜欢收藏地方戏曲的资料。"}, {"id": 7, "w": "鉴定", "p": "jiàndìng", "t": "动词", "m": "giám định, đánh giá và xác định", "coll": "鉴定真伪、专家鉴定", "s": "购买这件古董之前，他请专家鉴定了真伪。"}, {"id": 8, "w": "无偿", "p": "wúcháng", "t": "形容词", "m": "không thu tiền, không nhận thù lao hoặc đền đáp", "coll": "无偿捐赠、无偿提供", "s": "这位收藏家把珍藏多年的文物无偿捐赠给了博物馆。"}, {"id": 9, "w": "赠送", "p": "zèngsòng", "t": "动词", "m": "biếu, tặng", "coll": "赠送礼物、免费赠送", "s": "活动结束后，主办方向每位来宾赠送了一本纪念册。"}, {"id": 10, "w": "络绎不绝", "p": "luòyì bù jué", "t": "成语", "m": "đông như trẩy hội, nườm nượp không ngớt", "coll": "游客络绎不绝、络绎不绝的人群", "s": "展览开幕后，前来参观的游客络绎不绝。"}, {"id": 11, "w": "文物", "p": "wénwù", "t": "名词", "m": "di vật văn hóa, văn vật", "coll": "保护文物、珍贵文物", "s": "修建新道路时，施工单位特别注意保护附近的文物。"}, {"id": 12, "w": "同志", "p": "tóngzhì", "t": "名词", "m": "đồng chí", "coll": "老同志、同志们", "s": "这位老同志退休以后，仍然热心参与社区工作。"}, {"id": 13, "w": "打包", "p": "dǎ bāo", "t": "动词", "m": "đóng gói, đóng kiện", "coll": "打包行李、打包带走", "s": "搬家之前，她把书籍分类打包，方便整理。"}, {"id": 14, "w": "搭配", "p": "dāpèi", "t": "动词", "m": "phối hợp, kèm theo", "coll": "搭配颜色、合理搭配", "s": "设计这套服装时，她特别注意颜色的搭配。"}, {"id": 15, "w": "图案", "p": "tú'àn", "t": "名词", "m": "hoa văn, hình vẽ", "coll": "精美图案、传统图案", "s": "这块布上印着精美的传统图案。"}, {"id": 16, "w": "皇帝", "p": "huángdì", "t": "名词", "m": "hoàng đế, vua", "coll": "古代皇帝、皇帝的宫殿", "s": "导游介绍了这位古代皇帝在位时的重要事件。"}, {"id": 17, "w": "皇后", "p": "huánghòu", "t": "名词", "m": "hoàng hậu, vợ vua", "coll": "皇后服饰、皇后的画像", "s": "展厅里陈列着一幅古代皇后的画像。"}, {"id": 18, "w": "销毁", "p": "xiāohuǐ", "t": "动词", "m": "tiêu hủy", "coll": "销毁文件、集中销毁", "s": "过期的保密文件经过登记后，被统一销毁。"}, {"id": 19, "w": "手艺", "p": "shǒuyì", "t": "名词", "m": "tay nghề, sự lành nghề", "coll": "传统手艺、手艺精湛", "s": "爷爷的木工手艺十分精湛，做出的家具结实又美观。"}, {"id": 20, "w": "凝聚", "p": "níngjù", "t": "动词", "m": "tích tụ lại, ngưng tụ", "coll": "凝聚力量、凝聚心血", "s": "这座纪念馆凝聚了几代人的心血。"}, {"id": 21, "w": "结晶", "p": "jiéjīng", "t": "动词／名词", "m": "kết tinh; tinh thể; thành quả kết tinh", "coll": "智慧的结晶、劳动的结晶", "s": "这些精美的作品是工匠们智慧与劳动的结晶。"}, {"id": 22, "w": "籍贯", "p": "jíguàn", "t": "名词", "m": "quê quán", "coll": "填写籍贯、籍贯信息", "s": "填写表格时，请核对姓名和籍贯等信息。"}, {"id": 23, "w": "采购", "p": "cǎigòu", "t": "动词", "m": "thu mua, mua sắm (vật tư, hàng hóa)", "coll": "采购物资、集中采购", "s": "活动开始之前，工作人员统一采购了所需的物资。"}, {"id": 24, "w": "创业", "p": "chuàngyè", "t": "动词", "m": "lập nghiệp, sáng nghiệp", "coll": "自主创业、创业经历", "s": "毕业以后，他回到家乡自主创业。"}, {"id": 25, "w": "威望", "p": "wēiwàng", "t": "名词", "m": "uy danh, danh tiếng", "coll": "享有威望、崇高的威望", "s": "这位学者在专业领域内享有很高的威望。"}, {"id": 26, "w": "吝啬", "p": "lìnsè", "t": "形容词", "m": "keo kiệt, bủn xỉn", "coll": "为人吝啬、毫不吝啬", "s": "对于愿意学习的年轻人，他从不吝啬自己的经验。"}, {"id": 27, "w": "尚且", "p": "shàngqiě", "t": "连词", "m": "ngay cả… còn… (thường đi với 何况 để nhấn mạnh)", "coll": "尚且如此、尚且不能", "s": "这项任务连有经验的人尚且难以完成，更何况初学者。"}, {"id": 28, "w": "不惜", "p": "bùxī", "t": "动词", "m": "không tiếc, không quản, không ngại", "coll": "不惜代价、不惜花费", "s": "为了修复这件文物，专家们不惜花费大量时间和精力。"}, {"id": 29, "w": "可观", "p": "kěguān", "t": "形容词", "m": "lớn, đáng kể", "coll": "收入可观、数量可观", "s": "这家小店经营得当，每个月的收入相当可观。"}, {"id": 30, "w": "神圣", "p": "shénshèng", "t": "形容词", "m": "thần thánh, thiêng liêng", "coll": "神圣的职责、神圣的使命", "s": "在他看来，保护文化遗产是一项神圣的职责。"}, {"id": 31, "w": "使命", "p": "shǐmìng", "t": "名词", "m": "sứ mệnh", "coll": "肩负使命、完成使命", "s": "这支团队肩负着整理和保存历史资料的使命。"}, {"id": 32, "w": "看待", "p": "kàndài", "t": "动词", "m": "đối đãi, đánh giá", "coll": "正确看待、如何看待", "s": "面对不同意见，我们应该客观地看待问题。"}, {"id": 33, "w": "家属", "p": "jiāshǔ", "t": "名词", "m": "người nhà", "coll": "患者家属、通知家属", "s": "活动主办方邀请了获奖者及其家属共同出席典礼。"}, {"id": 34, "w": "拥护", "p": "yōnghù", "t": "动词", "m": "ủng hộ, tán thành, giúp đỡ", "coll": "拥护决定、得到拥护", "s": "这项改善环境的措施得到了居民们的拥护。"}, {"id": 35, "w": "表彰", "p": "biǎozhāng", "t": "动词", "m": "khen ngợi, tuyên dương", "coll": "公开表彰、受到表彰", "s": "学校举行大会，表彰了积极参与志愿服务的学生。"}, {"id": 36, "w": "荣誉", "p": "róngyù", "t": "名词", "m": "danh dự, vinh dự", "coll": "获得荣誉、集体荣誉", "s": "面对获得的荣誉，她始终保持谦虚。"}, {"id": 37, "w": "奖励", "p": "jiǎnglì", "t": "动词", "m": "khen thưởng", "coll": "给予奖励、奖励先进", "s": "公司决定奖励那些提出有效改进建议的员工。"}, {"id": 38, "w": "称号", "p": "chēnghào", "t": "名词", "m": "danh hiệu, danh nghĩa", "coll": "荣誉称号、授予称号", "s": "这位老师获得了优秀教育工作者的称号。"}, {"id": 39, "w": "争气", "p": "zhēngqì", "t": "动词", "m": "phấn đấu để không thua kém, làm rạng danh", "coll": "为家乡争气、十分争气", "s": "她希望通过自己的努力，为家乡争气。"}, {"id": 40, "w": "沾光", "p": "zhānguāng", "t": "动词", "m": "được hưởng lợi nhờ người khác, được thơm lây", "coll": "跟着沾光、大家沾光", "s": "村里修好了路，附近几个村的居民也跟着沾光。"}, {"id": 41, "w": "品质", "p": "pǐnzhì", "t": "名词", "m": "phẩm chất, tính cách", "coll": "优秀品质、产品品质", "s": "诚实守信是一种值得珍惜的优秀品质。"}, {"id": 42, "w": "乐意", "p": "lèyì", "t": "动词／形容词", "m": "sẵn lòng, vui lòng; vui vẻ, hài lòng", "coll": "乐意帮助、十分乐意", "s": "只要时间允许，她都乐意帮助有需要的人。"}, {"id": 43, "w": "精益求精", "p": "jīngyì qiújīng", "t": "成语", "m": "đã tốt còn cố làm tốt hơn, không ngừng trau chuốt", "coll": "精益求精的态度、不断精益求精", "s": "他对每一件作品都精益求精，连细小的瑕疵也不放过。"}, {"id": 44, "w": "次序", "p": "cìxù", "t": "名词", "m": "trật tự, thứ tự", "coll": "按照次序、排列次序", "s": "请大家按照次序进入展厅，不要拥挤。"}, {"id": 45, "w": "朝代", "p": "cháodài", "t": "名词", "m": "triều đại", "coll": "不同朝代、朝代更替", "s": "这张图表清楚地列出了不同朝代的先后顺序。"}, {"id": 46, "w": "泛滥", "p": "fànlàn", "t": "动词", "m": "tràn lan, lan tràn", "coll": "洪水泛滥、虚假信息泛滥", "s": "面对网络上泛滥的虚假信息，我们需要保持判断力。"}, {"id": 47, "w": "威信", "p": "wēixìn", "t": "名词", "m": "uy tín", "coll": "树立威信、失去威信", "s": "只有言行一致，才能在团队中树立威信。"}, {"id": 48, "w": "当代", "p": "dāngdài", "t": "名词", "m": "đương đại, ngày nay", "coll": "当代艺术、当代社会", "s": "这次展览汇集了多位当代艺术家的作品。"}, {"id": 49, "w": "级别", "p": "jíbié", "t": "名词", "m": "cấp bậc, cấp", "coll": "不同级别、提高级别", "s": "这项比赛分为不同级别，方便选手根据水平报名。"}, {"id": 50, "w": "泰斗", "p": "tàidǒu", "t": "名词", "m": "Thái Sơn Bắc Đẩu, ngôi sao sáng, người được mọi người tôn kính", "coll": "学界泰斗、一代泰斗", "s": "这位学者治学严谨，被同行誉为该领域的泰斗。"}];
